import{_ as e,c as a,o as t,a2 as n}from"./chunks/framework.DdOM6S6U.js";const m=JSON.parse('{"title":"ActiveNavigation","description":"","frontmatter":{"sidebarPos":2,"sidebarTitle":"ActiveNavigation"},"headers":[],"relativePath":"system-reference/backend/http/view-composers/active-navigation.md","filePath":"system-reference/backend/http/view-composers/active-navigation.md","lastUpdated":1778363927000}'),s={name:"system-reference/backend/http/view-composers/active-navigation.md"},o=n(`<h1 id="activenavigation" tabindex="-1">ActiveNavigation <a class="header-anchor" href="#activenavigation" aria-label="Permalink to &quot;ActiveNavigation&quot;">​</a></h1><p><strong>Class</strong>: <code>Unusualify\\Modularous\\Http\\ViewComposers\\ActiveNavigation</code><br><strong>Source</strong>: <code>src/Http/ViewComposers/ActiveNavigation.php</code></p><p>Parses the current route name into up to three navigation depth markers and injects them into every view. The frontend uses these variables to highlight the correct sidebar menu items.</p><h2 id="injected-variables" tabindex="-1">Injected Variables <a class="header-anchor" href="#injected-variables" aria-label="Permalink to &quot;Injected Variables&quot;">​</a></h2><table><thead><tr><th>Variable</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>_global_active_navigation</code></td><td><code>string</code></td><td>Second segment of the route name (index <code>[1]</code>) — the top-level module or section (e.g. <code>posts</code>)</td></tr><tr><td><code>_primary_active_navigation</code></td><td><code>string|null</code></td><td>Third segment (index <code>[2]</code>) — the sub-section or action (e.g. <code>index</code>). Falls back to the first route parameter when the route has fewer than three segments.</td></tr><tr><td><code>_secondary_active_navigation</code></td><td><code>string|null</code></td><td>Fourth segment (index <code>[3]</code>) — a nested sub-section. Collapses back to the primary segment when the fourth segment is <code>index</code>.</td></tr></tbody></table><h2 id="route-name-convention" tabindex="-1">Route Name Convention <a class="header-anchor" href="#route-name-convention" aria-label="Permalink to &quot;Route Name Convention&quot;">​</a></h2><p>All admin routes follow the pattern <code>admin.{module}.{action}.{sub}</code>. The composer splits on <code>.</code> and reads each depth:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Route name: admin.posts.index</span></span>
<span class="line"><span>  _global_active_navigation   = &#39;posts&#39;</span></span>
<span class="line"><span>  _primary_active_navigation  = &#39;index&#39;</span></span>
<span class="line"><span>  _secondary_active_navigation = (not set)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Route name: admin.posts.categories.edit</span></span>
<span class="line"><span>  _global_active_navigation    = &#39;posts&#39;</span></span>
<span class="line"><span>  _primary_active_navigation   = &#39;categories&#39;</span></span>
<span class="line"><span>  _secondary_active_navigation = &#39;edit&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Route name: admin.posts.categories.index</span></span>
<span class="line"><span>  _global_active_navigation    = &#39;posts&#39;</span></span>
<span class="line"><span>  _primary_active_navigation   = &#39;categories&#39;</span></span>
<span class="line"><span>  _secondary_active_navigation = &#39;categories&#39;  ← collapses &#39;index&#39; to parent</span></span></code></pre></div><h2 id="fallback-for-route-parameters" tabindex="-1">Fallback for Route Parameters <a class="header-anchor" href="#fallback-for-route-parameters" aria-label="Permalink to &quot;Fallback for Route Parameters&quot;">​</a></h2><p>When the route has only two segments but has route parameters (e.g. <code>admin.posts</code> with <code>{id}</code>), <code>_primary_active_navigation</code> is set to the value of the first route parameter. This handles resource show/edit routes that omit the action segment.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Does nothing when <code>$request-&gt;route()</code> returns <code>null</code> (console, queue, or test context without a bound route).</li><li>The composer uses <code>Arr::only()</code> to merge with any values already present on the view, so manually passed navigation overrides take precedence.</li></ul>`,12),i=[o];function r(c,d,p,l,h,v){return t(),a("div",null,i)}const g=e(s,[["render",r]]);export{m as __pageData,g as default};
